194		mustLimit(t, s, "P1", "SS", 15.0, at(1, 0))
195		smp1, err := s.Confirm("S1")
196		if err != nil {
197			t.Fatalf("Confirm after backfill: %v", err)
198		}
199		if smp1.Status != StatusConfirmed || !smp1.Exceeded {
200			t.Fatalf("expected confirmed & exceeded, got %+v", smp1)
201		}
202		// pH 取不晚于采样时间的最近一版（7.0@09-10），7.5 超标；SS 10 ≤ 15 达标
203		if smp1.Results[0].Limit != 7.0 || !smp1.Results[0].Exceeded {
204			t.Fatalf("pH result wrong: %+v", smp1.Results[0])
205		}
206		if smp1.Results[1].Limit != 15.0 || smp1.Results[1].Exceeded {
207			t.Fatalf("SS result wrong: %+v", smp1.Results[1])
208		}
209	
210		// 采样时间恰好等于生效时间时使用新值
211		mustSample(t, s, "S2", "P1", at(10, 0), Measurement{Item: "pH", Value: 7.5})
212		smp2, err := s.Confirm("S2")
213		if err != nil {
214			t.Fatalf("Confirm S2: %v", err)
215		}
216		if smp2.Results[0].Limit != 7.0 || !smp2.Results[0].LimitEffective.Equal(at(10, 0)) {
217			t.Fatalf("boundary effective time should use new value, got %+v", smp2.Results[0])
218		}
219		if !smp2.Exceeded {
220			t.Fatalf("7.5 > 7.0 should exceed")
221		}
222	
223		// 等于上限算达标
224		mustSample(t, s, "S3", "P1", at(11, 0), Measurement{Item: "pH", Value: 7.0})
225		smp3, _ := s.Confirm("S3")
226		if smp3.Exceeded || smp3.Results[0].Exceeded {
227			t.Fatalf("equal to limit should pass, got %+v", smp3.Results[0])
228		}
229	
230		// 重复确认直接返回已保存结果；之后补录限值不改变已确认结果
231		mustLimit(t, s, "P1", "pH", 100.0, at(10, 12))
232		again, err := s.Confirm("S2")
