234			t.Fatalf("re-confirm: %v", err)
235		}
236		if again.Results[0].Limit != 7.0 || !again.Exceeded {
237			t.Fatalf("confirmed result must not change, got %+v", again.Results[0])
238		}
239	
240		if _, err := s.Confirm("nope"); !errors.Is(err, ErrUnknownSample) {
241			t.Fatalf("unknown sample, got %v", err)
242		}
243	}
